python3 - <<'PY'
from pathlib import Path

Path("src/ps2/cdvd_rpc_historical_recovered.c").write_text('/*\n * Historical EE libcdvd RPC corridor recovered for SNES Station v0.23.\n * Target: 0x0019be70..0x0019c363.\n *\n * Primary historical source:\n *   iaddis/SNESticle, SNESticle/Modules/libcdvd/ee/cdvd_rpc.c\n *   commit 9590ebf3bf768424ebd6cb018f322e724a7aade3\n *\n * CDVD_GetSize() and CDVD_GETSIZE=0x08 survive in the closely-related PGEN\n * copy of the same libcdvd family:\n *   ps2homebrew/pgen, ps2/lib/cdvd_rpc.c\n *   commit f722681391fb6a1cc64a1260027a33862685e585\n *\n * This translation unit is intentionally self-contained for historical\n * compiler matching.  The compatibility declarations below preserve the\n * 32-bit EE ABI layout needed by this old RPC client without importing a\n * modern PS2SDK.\n */\n\ntypedef unsigned char u8;\ntypedef unsigned int u32;\ntypedef unsigned int size_t;\n\ntypedef void (*SifRpcEndFunc_t)(void *);\n\n/*\n * The historical client layout used by this binary has `server` at +0x24.\n * That exact offset is independently visible in CDVD_Init at 0x0019bea0.\n */\ntypedef struct SifRpcClientData_recovered {\n    u8 _before_server[0x24];\n    void *server;\n} SifRpcClientData_t;\n\nstruct TocEntry {\n    u32 fileLBA;\n    u32 fileSize;\n    u8 fileProperties;\n    u8 padding1[3];\n    char filename[128 + 1];\n    u8 padding2[3];\n} __attribute__((packed));\n\nenum CDVD_getMode {\n    CDVD_GET_FILES_ONLY = 1,\n    CDVD_GET_DIRS_ONLY = 2,\n    CDVD_GET_FILES_AND_DIRS = 3\n};\n\n#define CDVD_IRX        0x0B001337\n#define CDVD_FINDFILE   0x01\n#define CDVD_GETDIR     0x02\n#define CDVD_STOP       0x04\n#define CDVD_TRAYREQ    0x05\n#define CDVD_DISKREADY  0x06\n#define CDVD_FLUSHCACHE 0x07\n#define CDVD_GETSIZE    0x08\n\nextern int SifBindRpc(SifRpcClientData_t *client, int rpc_number, int mode);\nextern int SifCallRpc(SifRpcClientData_t *client, int rpc_number, int mode,\n                      void *send, int ssize, void *receive, int rsize,\n                      SifRpcEndFunc_t end_function, void *end_param);\nextern void SifWriteBackDCache(void *ptr, int size);\nextern char *strncpy(char *dest, const char *src, size_t n);\nextern void *memcpy(void *dest, const void *src, size_t n);\n\nint k_sceSifDmaStat(unsigned int id);\n\nstatic unsigned sbuff_recovered[0x1300] __attribute__((aligned(64)));\nstatic SifRpcClientData_t cd0_recovered;\n\nint cdvd_inited_recovered = 0;\n\n/* 0x0019be70 */\nint CDVD_Init_0019be70(void)\n{\n    int i;\n\n    while (1) {\n        if (SifBindRpc(&cd0_recovered, CDVD_IRX, 0) < 0)\n            return -1;\n\n        if (cd0_recovered.server != 0)\n            break;\n\n        i = 0x10000;\n        while (i--)\n            ;\n    }\n\n    cdvd_inited_recovered = 1;\n\n    return 0;\n}\n\n/* 0x0019bf00 */\nint CDVD_DiskReady_0019bf00(int mode)\n{\n    if (!cdvd_inited_recovered)\n        return -1;\n\n    sbuff_recovered[0] = mode;\n\n    SifCallRpc(&cd0_recovered, CDVD_DISKREADY, 0,\n               (void *)(&sbuff_recovered[0]), 4,\n               (void *)(&sbuff_recovered[0]), 4, 0, 0);\n\n    return sbuff_recovered[0];\n}\n\n/* 0x0019bf70 */\nint CDVD_FindFile_0019bf70(const char *fname, struct TocEntry *tocEntry)\n{\n    if (!cdvd_inited_recovered)\n        return -1;\n\n    strncpy((char *)&sbuff_recovered, fname, 1024);\n\n    SifCallRpc(&cd0_recovered, CDVD_FINDFILE, 0,\n               (void *)(&sbuff_recovered[0]), 1024,\n               (void *)(&sbuff_recovered[0]),\n               sizeof(struct TocEntry) + 1024, 0, 0);\n\n    memcpy(tocEntry, &sbuff_recovered[256], sizeof(struct TocEntry));\n\n    return sbuff_recovered[0];\n}\n\n/* 0x0019c0d0 */\nvoid CDVD_Stop_0019c0d0(void)\n{\n    if (!cdvd_inited_recovered)\n        return;\n\n    SifCallRpc(&cd0_recovered, CDVD_STOP, 0,\n               (void *)(&sbuff_recovered[0]), 0,\n               (void *)(&sbuff_recovered[0]), 0, 0, 0);\n\n    return;\n}\n\n/* 0x0019c128 */\nint CDVD_TrayReq_0019c128(int mode)\n{\n    (void)mode;\n\n    if (!cdvd_inited_recovered)\n        return -1;\n\n    SifCallRpc(&cd0_recovered, CDVD_TRAYREQ, 0,\n               (void *)(&sbuff_recovered[0]), 4,\n               (void *)(&sbuff_recovered[0]), 4, 0, 0);\n\n    return sbuff_recovered[0];\n}\n\n/* 0x0019c190 */\nint CDVD_getdir_0019c190(const char *pathname, const char *extensions,\n                         enum CDVD_getMode getMode,\n                         struct TocEntry tocEntry[],\n                         unsigned int req_entries, char *new_pathname)\n{\n    unsigned int num_entries;\n\n    if (!cdvd_inited_recovered)\n        return -1;\n\n    strncpy((char *)sbuff_recovered, pathname, 1023);\n\n    if (extensions == 0) {\n        sbuff_recovered[1024 / 4] = 0;\n    } else {\n        strncpy((char *)&sbuff_recovered[1024 / 4], extensions, 127);\n    }\n\n    sbuff_recovered[1152 / 4] = getMode;\n    sbuff_recovered[1156 / 4] = (int)tocEntry;\n    sbuff_recovered[1160 / 4] = req_entries;\n\n    SifWriteBackDCache(tocEntry, req_entries * sizeof(struct TocEntry));\n\n    SifCallRpc(&cd0_recovered, CDVD_GETDIR, 0,\n               (void *)(&sbuff_recovered[0]), 1024 + 128 + 4 + 4 + 4,\n               (void *)(&sbuff_recovered[0]), 4 + 1024, 0, 0);\n\n    num_entries = sbuff_recovered[0];\n\n    if (new_pathname != 0)\n        strncpy(new_pathname, (char *)&sbuff_recovered[1], 1023);\n\n    return num_entries;\n}\n\n/* 0x0019c2ac */\nvoid CDVD_FlushCache_0019c2ac(void)\n{\n    if (!cdvd_inited_recovered)\n        return;\n\n    SifCallRpc(&cd0_recovered, CDVD_FLUSHCACHE, 0,\n               (void *)(&sbuff_recovered[0]), 0,\n               (void *)(&sbuff_recovered[0]), 0, 0, 0);\n\n    return;\n}\n\n/* 0x0019c304 */\nunsigned int CDVD_GetSize_0019c304(void)\n{\n    /*\n     * Historical source really used a bare `return;` here despite the\n     * unsigned return type.  Preserve it: the target inactive path likewise\n     * leaves $v0 unspecified.\n     */\n    if (!cdvd_inited_recovered)\n        return;\n\n    SifCallRpc(&cd0_recovered, CDVD_GETSIZE, 0,\n               (void *)(&sbuff_recovered[0]), 0,\n               (void *)(&sbuff_recovered[0]), 4, 0, 0);\n\n    return sbuff_recovered[0];\n}\n', encoding="utf-8")
Path("analysis/matching/cdvd_rpc_listing.csv").write_text('address,end,name,object_symbol,source\n0x0019be70,0x0019bf00,CDVD_Init,CDVD_Init_0019be70,src/ps2/cdvd_rpc_historical_recovered.c\n0x0019bf00,0x0019bf70,CDVD_DiskReady,CDVD_DiskReady_0019bf00,src/ps2/cdvd_rpc_historical_recovered.c\n0x0019bf70,0x0019c0d0,CDVD_FindFile,CDVD_FindFile_0019bf70,src/ps2/cdvd_rpc_historical_recovered.c\n0x0019c0d0,0x0019c128,CDVD_Stop,CDVD_Stop_0019c0d0,src/ps2/cdvd_rpc_historical_recovered.c\n0x0019c128,0x0019c190,CDVD_TrayReq,CDVD_TrayReq_0019c128,src/ps2/cdvd_rpc_historical_recovered.c\n0x0019c190,0x0019c2ac,CDVD_getdir,CDVD_getdir_0019c190,src/ps2/cdvd_rpc_historical_recovered.c\n0x0019c2ac,0x0019c304,CDVD_FlushCache,CDVD_FlushCache_0019c2ac,src/ps2/cdvd_rpc_historical_recovered.c\n0x0019c304,0x0019c364,CDVD_GetSize,CDVD_GetSize_0019c304,src/ps2/cdvd_rpc_historical_recovered.c\n', encoding="utf-8")
Path("tools/run-cdvd-frontier.sh").write_text('#!/usr/bin/env bash\nset -euo pipefail\n\nROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"\ncd "$ROOT"\n\nDEFAULT_EE_CC="$ROOT/build/toolchains/ee-gcc-3.2.2-stage1/prefix/bin/ee-gcc"\nEE_CC="${EE_CC:-$DEFAULT_EE_CC}"\n\nif [[ ! -x "$EE_CC" ]]; then\n    echo "Missing historical EE compiler: $EE_CC" >&2\n    echo "Run: make bootstrap-ee-stage1" >&2\n    exit 2\nfi\n\nBUILD="$ROOT/build/matching/cdvd_rpc"\nmkdir -p "$BUILD"\n\nRAW="$BUILD/listing.bin"\nOBJ="$BUILD/cdvd_rpc_historical_recovered.o"\nREPORT="$ROOT/analysis/matching/cdvd-rpc-listing-report.md"\nLOG="$BUILD/frontier-run.log"\n\n# This libcdvd TU must permit GCC\'s fixed-size memcpy expansion.  The target\n# FindFile contains the resulting 0x90-byte inline copy, so do not use the\n# repository-wide -ffreestanding/-fno-builtin pair for this corridor.\nCDVD_EE_CFLAGS=(\n  -G0 -O2 -EL -pipe -Wall -Wa,-al\n  -fomit-frame-pointer -fstrict-aliasing -fno-common\n  -fshort-double\n  -mlong64 -mhard-float -mno-abicalls\n  -march=r5900 -mtune=r5900\n  -DPS2_EE -D_EE -DLSB_FIRST -DALIGN_DWORD -DCODE_PLATFORM=3\n)\n\nrm -f "$OBJ" "$REPORT" "$RAW" "$LOG" "$LOG.strict"\n\npython3 tools/objdump_listing_to_binary.py \\\n  --input analysis/functions/cdvd_rpc_0019be70.asm \\\n  --output "$RAW" \\\n  --base-address 0x0019be70 \\\n  --end-address 0x0019c364 >"$LOG" 2>&1\n\n"$EE_CC" "${CDVD_EE_CFLAGS[@]}" \\\n  -c src/ps2/cdvd_rpc_historical_recovered.c \\\n  -o "$OBJ" >>"$LOG" 2>&1\n\npython3 tools/compare_elf_functions.py \\\n  --target "$RAW" \\\n  --base-address 0x0019be70 \\\n  --object "$OBJ" \\\n  --manifest analysis/matching/cdvd_rpc_listing.csv \\\n  --report "$REPORT" >>"$LOG" 2>&1\n\npython3 tools/summarize_matching_report.py "$REPORT" >>"$LOG" 2>&1\n\necho "=== CDVD RPC frontier ==="\ngrep -E \'wrote analysis/matching/cdvd-rpc-listing-report|matching summary:|^[[:space:]]*(MATCH|MISS)[[:space:]]\' "$LOG" \\\n  | tail -n 24 || true\n\nif grep -q \'matching summary: 8/8\' "$LOG"; then\n    echo\n    echo "=== strict gate ==="\n    python3 tools/compare_elf_functions.py \\\n      --target "$RAW" \\\n      --base-address 0x0019be70 \\\n      --object "$OBJ" \\\n      --manifest analysis/matching/cdvd_rpc_listing.csv \\\n      --report "$REPORT" \\\n      --require-all-matching >"$LOG.strict" 2>&1\n    grep -E \'wrote analysis/matching/cdvd-rpc-listing-report|8/8\' "$LOG.strict" || true\n    echo "CDVD RPC strict listing gate: OK"\nfi\n\necho\necho "Full log: build/matching/cdvd_rpc/frontier-run.log"\n', encoding="utf-8")
Path("tools/test_progress43_cdvd_historical.py").write_text('from pathlib import Path\nimport csv\nimport unittest\n\nROOT = Path(__file__).resolve().parents[1]\n\n\nclass Progress43HistoricalCdvdTests(unittest.TestCase):\n    @classmethod\n    def setUpClass(cls):\n        cls.source = (ROOT / "src/ps2/cdvd_rpc_historical_recovered.c").read_text(\n            encoding="utf-8"\n        )\n\n    def test_all_eight_historical_functions_are_present(self):\n        for name in (\n            "CDVD_Init_0019be70",\n            "CDVD_DiskReady_0019bf00",\n            "CDVD_FindFile_0019bf70",\n            "CDVD_Stop_0019c0d0",\n            "CDVD_TrayReq_0019c128",\n            "CDVD_getdir_0019c190",\n            "CDVD_FlushCache_0019c2ac",\n            "CDVD_GetSize_0019c304",\n        ):\n            self.assertIn(name, self.source)\n\n    def test_historical_rpc_constants_include_getsize(self):\n        self.assertIn("#define CDVD_IRX        0x0B001337", self.source)\n        self.assertIn("#define CDVD_GETSIZE    0x08", self.source)\n\n    def test_client_server_field_matches_target_offset(self):\n        self.assertIn("u8 _before_server[0x24];", self.source)\n        self.assertIn("void *server;", self.source)\n\n    def test_toc_entry_has_historical_144_byte_shape(self):\n        self.assertIn("char filename[128 + 1];", self.source)\n        self.assertIn("} __attribute__((packed));", self.source)\n\n    def test_manifest_covers_target_corridor(self):\n        with (ROOT / "analysis/matching/cdvd_rpc_listing.csv").open(\n            newline="", encoding="utf-8"\n        ) as f:\n            rows = list(csv.DictReader(f))\n        self.assertEqual(8, len(rows))\n        self.assertEqual("0x0019be70", rows[0]["address"])\n        self.assertEqual("0x0019c364", rows[-1]["end"])\n\n    def test_runner_forces_fresh_candidate(self):\n        text = (ROOT / "tools/run-cdvd-frontier.sh").read_text(encoding="utf-8")\n        self.assertIn(\'rm -f "$OBJ"\', text)\n        self.assertIn("--require-all-matching", text)\n        self.assertNotIn("-ffreestanding", text)\n        self.assertNotIn("-fno-builtin", text)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', encoding="utf-8")
Path("docs/PROGRESS43.md").write_text("# Progress 43 — Historical libcdvd EE RPC corridor\n\nThis progress opens the corridor immediately following the matched Hiryu GSLIB\nhardware helpers: `0x0019be70..0x0019c363`.\n\nHistorical source evidence identifies all eight functions:\n\n1. `CDVD_Init`\n2. `CDVD_DiskReady`\n3. `CDVD_FindFile`\n4. `CDVD_Stop`\n5. `CDVD_TrayReq`\n6. `CDVD_getdir`\n7. `CDVD_FlushCache`\n8. `CDVD_GetSize`\n\nThe first seven survive in the SNESticle libcdvd source at commit\n`9590ebf3bf768424ebd6cb018f322e724a7aade3`.  `CDVD_GetSize` and command\n`CDVD_GETSIZE = 0x08` survive in the closely-related PGEN copy at commit\n`f722681391fb6a1cc64a1260027a33862685e585`.\n\nThe target itself confirms the old client ABI: `CDVD_Init` reads the RPC\nclient's `server` pointer at offset `+0x24`.\n\n`CDVD_FindFile` in the SNES Station target contains an inline fixed-size\n`memcpy` of the 0x90-byte `TocEntry`, unlike the surviving SNESticle listing\nwhich calls `memcpy`.  The corridor runner therefore uses a local historical\ncompiler profile without `-ffreestanding`/`-fno-builtin`, allowing GCC 3.2.2\nto expand that fixed-size copy.  This flag difference remains local to the\nCDVD experiment and does not alter the repository-wide EE contract.\n\nRun:\n\n```bash\n./tools/run-cdvd-frontier.sh\n```\n\nNo byte-match status is claimed until the comparator reports it.\n", encoding="utf-8")
